module TopModule (
    input  c,
    input  d,
    output [3:0] mux_in
);
    assign mux_in[0] = c | d;
    assign mux_in[1] = 1'b0;
    assign mux_in[2] = c & d;
    assign mux_in[3] = c | ~d;
endmodule

module tb_TopModule();
    reg a, b, c, d;
    wire [3:0] mux_in;
    wire mux_out;

    TopModule uut (
        .c(c),
        .d(d),
        .mux_in(mux_in)
    );

    // 4-to-1 mux model where select is {a, b} mapped to columns:
    // 00 -> mux_in[0]
    // 01 -> mux_in[1]
    // 11 -> mux_in[2]
    // 10 -> mux_in[3]
    assign mux_out = ({a, b} == 2'b00) ? mux_in[0] :
                     ({a, b} == 2'b01) ? mux_in[1] :
                     ({a, b} == 2'b11) ? mux_in[2] : mux_in[3];

    // Reference function derived directly from K-map table:
    //      ab
    //  cd  00  01  11  10
    //  00 | 0 | 0 | 0 | 1 |
    //  01 | 1 | 0 | 0 | 0 |
    //  11 | 1 | 0 | 1 | 1 |
    //  10 | 1 | 0 | 0 | 1 |
    function reg expected_out(input reg ia, input reg ib, input reg ic, input reg id);
        begin
            case ({ia, ib})
                2'b00: begin // ab = 00
                    case ({ic, id})
                        2'b00: expected_out = 1'b0; // cd = 00
                        2'b01: expected_out = 1'b1; // cd = 01
                        2'b11: expected_out = 1'b1; // cd = 11
                        2'b10: expected_out = 1'b1; // cd = 10
                    endcase
                end
                2'b01: begin // ab = 01
                    case ({ic, id})
                        2'b00: expected_out = 1'b0;
                        2'b01: expected_out = 1'b0;
                        2'b11: expected_out = 1'b0;
                        2'b10: expected_out = 1'b0;
                    endcase
                end
                2'b11: begin // ab = 11
                    case ({ic, id})
                        2'b00: expected_out = 1'b0;
                        2'b01: expected_out = 1'b0;
                        2'b11: expected_out = 1'b1;
                        2'b10: expected_out = 1'b0;
                    endcase
                end
                2'b10: begin // ab = 10
                    case ({ic, id})
                        2'b00: expected_out = 1'b1;
                        2'b01: expected_out = 1'b0;
                        2'b11: expected_out = 1'b1;
                        2'b10: expected_out = 1'b1;
                    endcase
                end
            endcase
        end
    endfunction

    integer i;
    reg exp;
    reg err_flag;

    initial begin
        err_flag = 0;
        for (i = 0; i < 16; i = i + 1) begin
            {a, b, c, d} = i[3:0];
            #1;
            exp = expected_out(a, b, c, d);
            if (mux_out !== exp) begin
                $display("FAIL: a=%b b=%b c=%b d=%b | mux_in=%b mux_out=%b expected=%b",
                         a, b, c, d, mux_in, mux_out, exp);
                err_flag = 1;
            end else begin
                $display("PASS: a=%b b=%b c=%b d=%b | mux_in=%b mux_out=%b",
                         a, b, c, d, mux_in, mux_out);
            end
        end

        if (err_flag) begin
            $display("SELFTEST FAIL: Mismatches detected.");
        end else begin
            $display("SELFTEST PASS");
        end
        $finish;
    end
endmodule
